  "Copy as Mermaid":"复制为 Mermaid",
  "Delete this diagram":"删除此图解",
  "Claude is reading the paper and drawing the diagram — this takes a minute or two.":"Claude 正在阅读论文并绘制图解——这需要一两分钟。",
  "You can keep working in the other tabs meanwhile.":"在此期间你可以继续在其他标签页中工作。",
