  "One per line: an arXiv id or link, a DOI or doi.org link, an OpenReview link - or BibTeX. arXiv and OpenReview papers arrive with their PDF. A DOI (or a publisher link that contains it) is looked up at doi.org and gets a PDF when a free copy is found (through OpenAlex, or on arXiv under the same title); otherwise the reference is added without one and you can attach the PDF later.":"每行一个：arXiv id 或链接、DOI 或 doi.org 链接、OpenReview 链接——或 BibTeX。arXiv 和 OpenReview 论文会连同 PDF 一起添加。DOI（或包含 DOI 的出版商链接）会在 doi.org 查询，找到免费版本时会获取 PDF（通过 OpenAlex，或在 arXiv 上按相同标题查找）；否则只添加文献信息，你可以稍后附加 PDF。",
