  "The language Claude writes a reading note's first draft in (“Generate first draft”), and the language of “Ask Claude” answers and figure captions in a note. The note's “More” menu changes the same setting.":"Claude 撰写阅读笔记初稿（“生成初稿”）所用的语言，也是笔记中“询问 Claude”的回答和图注所用的语言。笔记的“更多”菜单修改的是同一设置。",
  "First-draft language":"初稿语言",
  "Claude usage {0}":"Claude 用量 {0}",
  "How much the AI features (grouping, key points, drafts, diagrams, quizzes, explanations) may spend. The Claude panel is not affected.":"AI 功能（分组、要点、草稿、图解、测验、讲解）可以花费多少。Claude 面板不受影响。",
  "Claude usage":"Claude 用量",
  "Economy — least tokens: quick answers, a lighter model for small tasks, drafts from the text only (no figures)":"节省——token 最少：快速回答，小任务使用更轻量的模型，草稿只根据文本生成（不含图）",
  "Balanced — quick small tasks, careful diagrams, quizzes and drafts (recommended)":"均衡——小任务快速完成，图解、测验和草稿认真完成（推荐）",
  "Best quality — Claude thinks as long as it wants; uses the most tokens":"最佳质量——Claude 想多久就思考多久；使用最多 token",
  "How Claude explains {0}":"Claude 如何讲解 {0}",
  "This instruction is added to every explanation automatically — in the Claude panel, “Ask Claude” in a note, diagram examples and quiz explanations — so you never have to type it. Edit it to change how Claude teaches.":"这条指令会自动添加到每次讲解中——包括 Claude 面板、笔记中的“询问 Claude”、图解示例和测验解析——这样你就无需每次输入。编辑它即可改变 Claude 的讲解方式。",
  "How Claude explains":"Claude 如何讲解",
  "Put the built-in teaching style back":"恢复内置的讲解风格",
  "Reset to the built-in style":"重置为内置风格",
  "Research lines Claude should prefer {0}":"Claude 应优先使用的研究方向 {0}",
  "When Claude groups your papers it files each one under the research line it builds on (its background, preliminaries and the methods it extends), not its application words. One line per row, optionally “Name: what belongs there”; write “Line / Sub-line” for a sub-line. Claude prefers these names and adds a line only when none fits. An empty box gives Claude no preferred lines; “Reset to the built-in lines” brings the list back.":"Claude 为你的论文分组时，会把每篇论文归入它所基于的研究方向（其背景、预备知识和所扩展的方法），而不是它的应用领域。每行一个方向，可写成“名称: 归入的内容”；子方向写作“方向 / 子方向”。Claude 会优先使用这些名称，只有在都不合适时才新增方向。框为空表示不给 Claude 任何偏好方向；“重置为内置方向”可恢复列表。",
  "Research lines Claude should prefer":"Claude 应优先使用的研究方向",
