  "Draft related work from your library":"根据你的文献库起草相关工作",
  "Claude writes LaTeX from your reading notes, key points and briefs — not from the PDFs — and cites only the papers you tick.":"Claude 会根据你的阅读笔记、要点和简介——而不是 PDF——写出 LaTeX，并且只引用你勾选的论文。",
  "What this part should bring out (optional, one line)":"这部分要突出什么（可选，一行）",
