  "Guide: how to use ResearchTool":"指南：如何使用 ResearchTool",
  "Export references: write references.bib, notes.md, library.csv and the reading notes to the export folder":"导出参考文献：把 references.bib、notes.md、library.csv 和阅读笔记写到导出文件夹",
  "Settings: export folder":"设置：导出文件夹",
