  "or":"或",
  "Yes":"是",
  "No":"否",
  "Lineage":"脉络",
  "(Library toolbar; “Lineage of this line…” in the ⋯ of a line; “Lineage of this paper” in the Related tab) shows where a set of your papers comes from and where the work went, as Connected Papers does.":"（文献库工具栏；方向的 ⋯ 菜单中的“此方向的脉络…”；“相关”标签页中的“这篇论文的脉络”）显示你的一组论文从何而来、后续工作走向何处，类似 Connected Papers。",
  "Custom set…":"自定义集合…",
  "- tick several lines and sub-lines and / or type words a paper's title, tags or category must contain, and give the set a name; it is kept under “Your sets”.":"——勾选几个方向和子方向，和 / 或输入论文标题、标签或类别必须包含的词，并为集合命名；它会保存在“你的集合”下。",
  "The papers of the set are listed on the left before anything is looked up. Untick one to leave it out, then":"在进行任何查询之前，集合中的论文会列在左侧。取消勾选可将其排除，然后",
  "Look up the other N":"查询其余 N 篇",
  "Look up the lineage":"查询脉络",
  "; the window says beforehand how many papers are looked up already and about how many OpenAlex queries it takes (at most 10). A set that has no result of its own yet - the library with one new paper - shows the closest earlier result at once, marked “Computed for 112 papers · 1 new not included”, with":"；窗口会事先说明已有多少篇论文查询过，以及大约需要多少次 OpenAlex 查询（最多 10 次）。尚无自身结果的集合——例如新增了一篇论文的文献库——会立即显示最接近的早期结果，并标注“基于 112 篇论文计算 · 1 篇新论文未包含”，并提供",
  "Update":"更新",
  "computes again.":"重新计算。",
  "History line":"发展脉络",
  "Citations":"引用",
  "for a menu.":"打开菜单。",
  "Ancestry":"源流",
  ": the 8 works the set builds on most, in a column on the left, with a bundle into each lane as wide as the number of its papers that cite it. Papers take the colour of their main ancestor. Click an ancestor or a lane name to see just its edges; a dashed ring marks an ancestor most of whose citers are from the last 12 months.":"：集合最主要基于的 8 篇工作列在左侧一栏，连向每条泳道的线束宽度等于该泳道中引用它的论文数。论文采用其主要源头的颜色。点击某个源头或泳道名称即可只看它的连线；虚线圆圈表示引用它的论文大多来自最近 12 个月。",
  "saves the picture for slides or a proposal.":"保存图片，用于幻灯片或申请书。",
  "Prior, derivative and similar works":"前序、后续和相似工作",
  "Prior works":"前序工作",
  "are the works your papers cite most;":"是你的论文引用最多的工作；",
  "Derivative works":"后续工作",
  "cite several of them, including the most cited of the last 18 months;":"引用了其中的多篇，包括最近 18 个月中被引最多的；",
  "Similar":"相似",
  "are works the papers citing yours also cite, or that share many of your references - related and concurrent work that does not cite you.":"是引用你论文的论文同样引用的工作，或与你的参考文献大量重合的工作——即没有引用你的相关和同期工作。",
  "“Most relevant” comes first: hub papers cited everywhere count less, and generic works (Adam, ResNet, a benchmark everyone uses) are hidden until you show them. Hover a row to read why it ranks where it does; the chips say who cites it, how many references it shares, and Seminal / Recent / Rising.":"“最相关”排在最前：到处被引用的枢纽论文权重较低，通用工作（Adam、ResNet、人人都用的基准）在你显示之前会被隐藏。把鼠标悬停在某一行上可查看其排名原因；标签显示谁引用了它、共享多少参考文献，以及开创性 / 最新 / 上升中。",
  "For a prior work the details show how your papers cite it - “uses its method”, “influential” and the citing sentences from Semantic Scholar (asked when you select it, a few papers at a time). Above the table: the top foundations you don't have yet.":"对于前序工作，详情会显示你的论文如何引用它——“使用其方法”“有影响力”以及来自 Semantic Scholar 的引用句（在你选中时查询，每次几篇）。表格上方：你还没有的最重要基础工作。",
  "A line so new that few works cite it says so;":"很新、几乎没有工作引用的方向会明确说明；",
  "Recent works citing your line's top ancestors":"引用你方向主要源头的最新工作",
  "lists the newest work around it.":"会列出它周围的最新工作。",
  "Filter by years, missing from your library or project, surveys, venue type or open PDF; tick rows to act on just those.":"可按年份、文献库或项目中缺失、综述、发表类型或开放 PDF 筛选；勾选行即可只对它们操作。",
  "Into your library and your project":"加入你的文献库和项目",
  "adds a work to your library. The bookmark":"把一篇工作添加到你的文献库。书签",
  "adds it to the project shown on the project chip (the project of the set, the one you pick, or the working project - picking one here does not change your working project); works you don't have are imported first.":"会把它添加到项目标签所显示的项目（集合的项目、你选择的项目或当前项目——在这里选择不会改变你的当前项目）；你还没有的工作会先被导入。",
  "For a paper of yours,":"对于你自己的论文，",
  "chooses which of its neighbours to add.":"选择要添加它的哪些相邻工作。",
  "Grouped…":"分组…",
  "exports Foundational / Recent / Surveys as BibTeX, or copies them as a related-work bullet list.":"把基础 / 最新 / 综述导出为 BibTeX，或复制为相关工作的项目符号列表。",
  "leaves a":"会在左下角留下一个",
  "Back to Lineage":"返回脉络",
  "button at the bottom left that brings the window back with the same tab, selection and scroll.":"按钮，可让窗口以相同的标签页、选择和滚动位置重新打开。",
  "Only DOIs, arXiv ids and OpenAlex ids are sent - never a note, a title or a PDF. Answers are kept on this Mac (papers for 14 days, a computed set for 7).":"只发送 DOI、arXiv id 和 OpenAlex id——绝不发送笔记、标题或 PDF。结果保存在这台 Mac 上（论文 14 天，计算过的集合 7 天）。",
