  ": the contents button opens the table of contents of the PDF. Citations such as [23], \"Fig. 4\" or \"Sec. 3.2\" are links: rest the pointer on one to see a small picture of its target, click to go there. The Back button ({0}[) returns to where you were before a jump. Web addresses open in a new tab.":"：目录按钮会打开 PDF 的目录。[23]、\"Fig. 4\" 或 \"Sec. 3.2\" 这样的引用都是链接：把鼠标停在上面可看到目标的小预览，点击即可跳转。返回按钮（{0}[）可回到跳转之前的位置。网址会在新标签页中打开。",
  "Details holds the bibliographic fields, reading status, star, category, tags, the brief (edit it, or let Claude write it again with":"“详情”包含文献字段、阅读状态、星标、类别、标签和简介（可以编辑，或让 Claude 重新撰写，使用",
