  "Delete the box “{0}” and its {1} arrow? Its explanation and examples are deleted with it. Undo in the bar brings it back.":"删除方框“{0}”及其 {1} 个箭头？其解释和示例也会一并删除。工具栏中的撤销可以恢复。",
  "Delete the folder “{0}” and everything in it? It is moved to the workspace trash, not permanently deleted.":"删除文件夹“{0}”及其中的所有内容？它会被移到工作区废纸篓，不会永久删除。",
  "Delete everything that has been in the trash for more than {0} days for good? {1} of deleted papers, replaced PDFs and deleted project files are removed from this Mac. This cannot be undone.":"永久删除在废纸篓中超过 {0} 天的所有内容？已删除论文、被替换的 PDF 和删除的项目文件共 {1} 将从这台 Mac 上移除。此操作无法撤销。",
