  "(no title)":"（无标题）",
  "Library panel":"文献库面板",
  "(the books button in the icon rail on the left, or {0}): your whole library beside the text, the papers of this project first, then one group per research line. Search by title, author, year or cite key. Click papers to select them, then":"（左侧图标栏中的书本按钮，或 {0}）：在正文旁显示你的整个文献库，此项目的论文排在最前，其余按研究方向分组。可按标题、作者、年份或引用键搜索。单击论文将其选中，然后",
  "puts one":"会在光标处插入一个",
  "at the cursor; double-click a paper or drag it into the text to cite it there. Point at a paper to add it to the project, take it out, or open it in the Library.":"；双击论文或把它拖入正文，即可在该处引用。指向某篇论文可将其添加到项目、移出项目，或在文献库中打开。",
  // Lineage window (lineage.js), translation pass: the window, its tables, menus, dialogs and toasts
  "Choose the set at the top: the whole library, a research line or sub-line, a project's papers, one paper, or":"在顶部选择集合：整个文献库、一个研究方向或子方向、某个项目的论文、一篇论文，或",
  ": your papers on a time axis, one lane per line, an arrow from a paper to each later paper of yours that cites it; the most relevant prior works can be shown as nodes of their own (filled when you have them). Hover for the title, click for details, double-click to open, right-click or":"：你的论文排在时间轴上，每个方向一条泳道，从一篇论文画箭头指向你每篇引用它的较晚论文；最相关的前序工作可以作为单独的节点显示（你已拥有的为实心）。悬停查看标题，单击查看详情，双击打开，右键或",
  "takes the first 25 rows as sorted unless you change the number. One message sums it up; its Undo takes them out of the project again and leaves them in your library.":"会按当前排序取前 25 行，除非你修改数量。完成后有一条消息汇总；其中的撤销会把它们再移出项目，但保留在你的文献库中。",
