  "This computation asked OpenAlex {0} single look-ups (free) and {1} list queries (at most 10; ~1000 a day for this network), Semantic Scholar {2} times. Today: {3} list queries in all. Only DOIs, arXiv ids and OpenAlex ids were sent.":"本次计算向 OpenAlex 发出 {0} 次单篇查询（免费）和 {1} 次列表查询（最多 10 次；此网络每天约 1000 次），向 Semantic Scholar 请求 {2} 次。今天共 {3} 次列表查询。只发送了 DOI、arXiv id 和 OpenAlex id。",
  ", {0} to look up (free single look-ups)":"，{0} 篇待查询（免费单篇查询）",
  ", {0} without DOI or arXiv id":"，{0} 篇没有 DOI 或 arXiv id",
  "{0} of {1} papers already looked up{2}{3}; about {4} list {5} (at most {6} per computation; {7} used today of OpenAlex's ~1000).":"{1} 篇论文中已查询 {0} 篇{2}{3}；约需 {4} 次列表查询（每次计算最多 {6} 次；今天已用 OpenAlex 约 1000 次中的 {7} 次）。",
  "this paper comes":"这篇论文来自",
  "Where {0} from, and where the work went.":"{0}从何而来，相关工作又走向了哪里。",
  "The history line":"发展脉络",
  "lays them out in time, one lane per research line, with an arrow from a paper to each later paper of yours that cites it.":"把它们按时间排开，每个研究方向一条泳道，从一篇论文画箭头指向你每篇引用它的较晚论文。",
  "are the papers yours cite most - usually the seminal works the line builds on.":"是你的论文引用最多的论文——通常是该方向所依托的奠基性工作。",
  "cite many of yours - surveys and the newest work of the line. (The same ideas as Connected Papers.)":"引用了你的许多论文——综述以及该方向的最新工作。（思路与 Connected Papers 相同。）",
  "Each paper is looked up once by its DOI or arXiv id at OpenAlex (free), and at Semantic Scholar when OpenAlex has no reference list. The two lists then take at most 10 OpenAlex list queries out of its daily allowance. Nothing else leaves this Mac - never a note, a title or the PDF. The answer is kept for a week.":"每篇论文按 DOI 或 arXiv id 在 OpenAlex 上查询一次（免费），OpenAlex 没有参考文献列表时再查询 Semantic Scholar。随后两份列表最多占用 OpenAlex 每日配额中的 10 次列表查询。其他任何内容都不会离开这台 Mac——绝不发送笔记、标题或 PDF。结果会保留一周。",
  "Looking up paper {0} of {1}{2}":"正在查询第 {0} / {1} 篇论文{2}",
  "Counting the prior works and fetching their records…":"正在统计前序工作并获取其记录…",
  "Asking OpenAlex which works cite these papers…":"正在向 OpenAlex 查询哪些工作引用了这些论文…",
  "So far: {0} OpenAlex look-ups, {1} list queries, {2} Semantic Scholar requests.":"目前：{0} 次 OpenAlex 查询，{1} 次列表查询，{2} 次 Semantic Scholar 请求。",
  "Semantic Scholar is asked about one paper a second, so a large library takes a few minutes the first time; later only new papers are looked up. You can close this window - the computation goes on and is kept.":"Semantic Scholar 每秒只查询一篇论文，所以大型文献库第一次需要几分钟；之后只查询新论文。你可以关闭此窗口——计算会继续进行并保存结果。",
