  "Which works inspired which: the 8 works these papers build on most, with a bundle into each lane (width = how many of its papers cite it)":"哪些工作启发了哪些：这些论文最依赖的 8 项工作，每条泳道有一束连线汇入（宽度 = 该泳道中引用它的论文数）",
