  "to stop it), or “Check venue again” when you right-click a paper. It asks Crossref, PMLR (for CoRL, ICML … when arXiv or an index names the conference), DBLP, OpenAlex, Semantic Scholar and arXiv, one paper after the other, sending only the DOI, arXiv id or title. A venue counts only when the publisher's own record names it, or two of these indexes name the same venue and year, or DBLP lists the very paper; an “Accepted to …” comment on arXiv alone is shown as a claim, not trusted. Rest the pointer on a group or on the venue of a row to see the full name and which indexes confirmed it; Details shows the same, or why the venue is not verified, with":"停止），或右键点击论文选择“重新检查发表信息”。它会依次查询 Crossref、PMLR（当 arXiv 或某个索引给出会议名称时，用于 CoRL、ICML …）、DBLP、OpenAlex、Semantic Scholar 和 arXiv，一次一篇，只发送 DOI、arXiv id 或标题。只有出版方自己的记录写明了发表处，或其中两个索引给出相同的发表处和年份，或 DBLP 收录了这篇论文本身时，发表信息才算数；仅凭 arXiv 上的“Accepted to …”备注只显示为声明，不予采信。把指针停在某个分组或某行的发表处上，可查看完整名称以及哪些索引确认了它；“详情”中也显示同样的信息，或说明为何未验证，并提供",
